-- Bistrô Teste: cada prato ganha uma foto real, em alta resolução (1080×1350) e de
-- licença livre (Unsplash License), escolhida para mostrar o prato do cardápio.
-- Os arquivos ficam em public/cardapio/bistro; o crédito (autor, página e
-- licença) vai em menu_config.photoCredit. O volume 3D antigo pertencia às fotos
-- trocadas, então sai e é gerado de novo pelo Studio. Pratos cuja foto mostrava
-- outra coisa foram ajustados à foto. O suco de caju mantém a foto própria.
do $$
declare rid uuid;
begin
  select id into rid from public.restaurants where slug = 'bistro-teste';
  if rid is null then return; end if;

  update public.pdv_menu_items m
  set image_url = f.url,
      depth_url = null,
      name = coalesce(f.name, m.name),
      description = coalesce(f.description, m.description),
      menu_config = coalesce(m.menu_config, '{}'::jsonb) || jsonb_build_object('photoCredit', f.credit::jsonb)
  from (values
    ('MAR-ISCA', 'https://tipe.digital/cardapio/bistro/mar-isca.webp', 'Isca de peixe com fritas', 'Tiras de peixe empanadas com batata frita, limão e molho tártaro da casa.', '{"imageUrl": "https://tipe.digital/cardapio/bistro/mar-isca.webp", "illustrative": true, "author": "@winstontjia no Unsplash", "sourceUrl": "https://unsplash.com/photos/DyGo_AGOQwI", "license": "Unsplash License", "licenseUrl": "https://unsplash.com/license", "changes": "Recortada em 4:5 e reduzida para 1080×1350."}'),
    ('BT-DADINHO', 'https://tipe.digital/cardapio/bistro/bt-dadinho.webp', null, null, '{"imageUrl": "https://tipe.digital/cardapio/bistro/bt-dadinho.webp", "illustrative": true, "author": "@lingchor no Unsplash", "sourceUrl": "https://unsplash.com/photos/PG5W85aaC4k", "license": "Unsplash License", "licenseUrl": "https://unsplash.com/license", "changes": "Recortada em 4:5 e reduzida para 1080×1350."}'),
    ('BT-CALDINHO', 'https://tipe.digital/cardapio/bistro/bt-caldinho.webp', null, null, '{"imageUrl": "https://tipe.digital/cardapio/bistro/bt-caldinho.webp", "illustrative": true, "author": "@ffkae no Unsplash", "sourceUrl": "https://unsplash.com/photos/9b_UDAe0XVQ", "license": "Unsplash License", "licenseUrl": "https://unsplash.com/license", "changes": "Recortada em 4:5 e reduzida para 1080×1350."}'),
    ('BT-CARNESOL', 'https://tipe.digital/cardapio/bistro/bt-carnesol.webp', 'Carne de sol na chapa', 'Carne de sol em cubos na chapa, com macaxeira frita, arroz e vinagrete.', '{"imageUrl": "https://tipe.digital/cardapio/bistro/bt-carnesol.webp", "illustrative": true, "author": "@marcelodlt no Unsplash", "sourceUrl": "https://unsplash.com/photos/BnkjG7OZzMw", "license": "Unsplash License", "licenseUrl": "https://unsplash.com/license", "changes": "Recortada em 4:5 e reduzida para 1080×1350."}'),
    ('BT-SALADA', 'https://tipe.digital/cardapio/bistro/bt-salada.webp', 'Salada de manga e abacate', 'Folhas verdes, manga, tomate, abacate e molho de limão.', '{"imageUrl": "https://tipe.digital/cardapio/bistro/bt-salada.webp", "illustrative": true, "author": "@bmarie97 no Unsplash", "sourceUrl": "https://unsplash.com/photos/KFACa2ZwfW4", "license": "Unsplash License", "licenseUrl": "https://unsplash.com/license", "changes": "Recortada em 4:5 e reduzida para 1080×1350."}'),
