    ('BT-PUDIM', 'https://tipe.digital/cardapio/bistro/bt-pudim.webp', null, null, '{"imageUrl": "https://tipe.digital/cardapio/bistro/bt-pudim.webp", "illustrative": true, "author": "@pires128 no Unsplash", "sourceUrl": "https://unsplash.com/photos/TqPdzQ00I0U", "license": "Unsplash License", "licenseUrl": "https://unsplash.com/license", "changes": "Recortada em 4:5 e reduzida para 1080×1350."}'),
    ('MAR-COCO', 'https://tipe.digital/cardapio/bistro/mar-coco.webp', null, null, '{"imageUrl": "https://tipe.digital/cardapio/bistro/mar-coco.webp", "illustrative": true, "author": "@xiaoyulifish no Unsplash", "sourceUrl": "https://unsplash.com/photos/tW0j8n-GIUY", "license": "Unsplash License", "licenseUrl": "https://unsplash.com/license", "changes": "Recortada em 4:5 e reduzida para 1080×1350."}'),
    ('BT-LIMONADA', 'https://tipe.digital/cardapio/bistro/bt-limonada.webp', 'Limonada com hortelã', 'Limão, hortelã e gelo, copo de 400 ml.', '{"imageUrl": "https://tipe.digital/cardapio/bistro/bt-limonada.webp", "illustrative": true, "author": "@july_06 no Unsplash", "sourceUrl": "https://unsplash.com/photos/WDgN0XclV_w", "license": "Unsplash License", "licenseUrl": "https://unsplash.com/license", "changes": "Recortada em 4:5 e reduzida para 1080×1350."}'),
