    ('BT-CAIPI', 'https://tipe.digital/cardapio/bistro/bt-caipi.webp', null, null, '{"imageUrl": "https://tipe.digital/cardapio/bistro/bt-caipi.webp", "illustrative": true, "author": "@mateusz_feliksik no Unsplash", "sourceUrl": "https://unsplash.com/photos/ZQ568s1d7_o", "license": "Unsplash License", "licenseUrl": "https://unsplash.com/license", "changes": "Recortada em 4:5 e reduzida para 1080×1350."}'),
